<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\News;use Illuminate\Http\Request;use Illuminate\Support\{Str,Facades\Storage};
class NewsController extends Controller{public function index(){return view('admin.news.index',['items'=>News::latest()->paginate(20)]);}public function create(){return view('admin.news.form',['item'=>new News]);}public function store(Request $r){News::create($this->data($r));return redirect()->route('admin.news.index')->with('ok','Новость создана');}public function edit(News $news){return view('admin.news.form',['item'=>$news]);}public function update(Request $r,News $news){$old=$news->cover;$d=$this->data($r,$news);$news->update($d);if(isset($d['cover'])&&$old&&$old!==$d['cover'])Storage::disk('public')->delete($old);return redirect()->route('admin.news.index')->with('ok','Новость обновлена');}public function destroy(News $news){if($news->cover)Storage::disk('public')->delete($news->cover);$news->delete();return back()->with('ok','Новость удалена');}private function data(Request $r,?News $item=null):array{$d=$r->validate(['title'=>'required|max:255','excerpt'=>'nullable','content'=>'nullable','published_at'=>'nullable|date','cover'=>'nullable|image|max:10240']);$d['slug']=$this->slug($r->input('slug')?:$d['title'],$item?->id);if($r->hasFile('cover'))$d['cover']=$r->file('cover')->store('news','public');$d['is_published']=$r->boolean('is_published');return $d;}private function slug($v,$ignore=null){$base=Str::slug($v)?:'news';$s=$base;$i=2;while(News::where('slug',$s)->when($ignore,fn($q)=>$q->where('id','!=',$ignore))->exists())$s=$base.'-'.$i++;return $s;}}